static String run() {
    StringBuilder log = new StringBuilder();
    try {
        log.append("a");
        Integer.parseInt("x");
        log.append("b");
    } catch (NumberFormatException e) {
        log.append("c");
    } finally {
        log.append("d");
    }
    log.append("e");
    return log.toString();
}

System.out.println(run());

